You will be provided with two pseudo code snippets which are extracted from two stripped binaries with different compilation settings (i.e., architecture, compiler, optimization), namely Code A and Code B. Your task is to determine whether the two code snippets are compiled from the same source code. The binaries are stripped so that you can not determine the result based on the different variable names (e.g., v1, v2) and function call names (e.g., sub_893B4).
You answer should return as in the following format: 
<same_source>yes or no</same_source>
<explanation>explanation no more than 150 words</explanation>

Code A: void __fastcall sub_3F3F8(void **ptr)
{
  void *v2; 
  void **v3; 
  void *v4; 

  v2 = *ptr;
  if ( v2 != nullptr )
  {
    v3 = ptr;
    do
    {
      free(ptr: v2);
      v4 = v3[1];
      ++v3;
      v2 = v4;
    }
    while ( v4 != nullptr );
  }
  free(ptr);
} 

Code B: void __fastcall sub_430BE0(void **ptr)
{
  void *v2; 
  void **v3; 

  v2 = *ptr;
  if ( v2 != nullptr )
  {
    v3 = ptr;
    do
    {
      ++v3;
      free(ptr: v2);
      v2 = *v3;
    }
    while ( *v3 != nullptr );
  }
  free(ptr);
}
